#!/usr/bin/env python3
"""SIGNATURE MASTER: signature toolkit (ids + stamps + hashes + lineage)."""
import hashlib, re
def hid(t): return hashlib.sha256(t.encode()).hexdigest()[:8].upper()
class Kit:
    def __init__(self): self.n=1; self.reg={}; self.parent={}
    def create(self,title,parent=None):
        sid="JAH-SPEC-%06d"%self.n; self.n+=1
        stamp="SIG-"+hid(sid+title)[:12]
        self.reg[sid]={"title":title,"stamp":stamp,"hash":hid(title)}
        if parent: self.parent[sid]=parent
        return sid
    def verify(self,sid,title): return self.reg[sid]["stamp"]=="SIG-"+hid(sid+title)[:12]

if __name__ == "__main__":
    k=Kit(); a=k.create("Planter"); b=k.create("Planter v2",parent=a)
    assert k.verify(a,"Planter") and not k.verify(a,"Planter!")
    assert re.match(r"^JAH-SPEC-\d{6}$",b)
    print("registry:",{s:v["stamp"] for s,v in k.reg.items()})
    print("OK: toolkit mints, stamps, and verifies")

#!/usr/bin/env python3
"""SIGNATURE MASTER: wordplay studio (pig + scramble + morse + banner + acronym)."""
import random
MORSE={"A":".-","B":"-...","C":"-.-.","D":"-..","E":".","H":"....","J":".---","L":".-..","O":"---","R":".-."}
VOW=set("aeiou")
def pig(w):
    w=w.lower(); i=0
    while i<len(w) and w[i] not in VOW: i+=1
    return (w if i==0 else w[i:]+w[:i])+("way" if i==0 else "ay")
def scramble(w,seed=1):
    r=random.Random(seed)
    if len(w)<=3: return w
    m=list(w[1:-1]); r.shuffle(m); return w[0]+"".join(m)+w[-1]
def morse(t): return " ".join(MORSE[c] for c in t.upper() if c in MORSE)
SKIP={"of","the"}
def acronym(p): return "".join(w[0].upper() for w in p.split() if w.lower() not in SKIP)

if __name__ == "__main__":
    w="hello"
    print("pig:",pig(w),"| scramble:",scramble(w),"| morse:",morse("JAH"))
    assert pig("hello")=="ellohay" and morse("JAH")==".--- .- ...."
    assert acronym("Wordplay Studio")=="WS"
    print("OK: all five wordplay transforms work")

