        print(n,roman(n),words(n),fb(n))
    assert roman(14)=="XIV" and words(7)=="seven" and fb(15)=="FizzBuzz"
    print("OK: number systems lab verified")

#!/usr/bin/env python3
"""SIGNATURE MASTER: game arcade (hangman + RPS + coin + countdown)."""
import random
def hangman(w,guesses): return set(w)<=set(g for g in guesses if g in w)
BEATS={"rock":"scissors","scissors":"paper","paper":"rock"}
def rps(p,c): return "tie" if p==c else ("win" if BEATS[p]==c else "lose")

if __name__ == "__main__":
    rng=random.Random(2)
    assert hangman("jah",["j","a","h"])
    assert rps("paper","rock")=="win"
    flips=sum(rng.random()<0.5 for _ in range(2000))
    assert 900<flips<1100
    seq=[i for i in range(3,0,-1)]
    assert seq==[3,2,1]
    print("hangman: won | RPS: paper beats rock | coin: %d/2000 heads | countdown ok"%flips)
    print("OK: arcade games all work")

