"""SIGNATURE MASTER: audit tools (validate + lineage + hash + sample)."""
import hashlib, re
def valid(rec): return bool(re.match(r"^JAH-[A-Z]+-\d+$",rec["id"])) and rec["rank"] in (1,2,3)
def audit(recs):
    bad=[r["id"] for r in recs if not valid(r)]
