"""SIGNATURE MASTER: master console — every Signature family in one run."""
import hashlib, random
def hid(t): return hashlib.sha256(t.encode()).hexdigest()[:8].upper()
def prng(seed):
    a=seed&0xFFFFFFFF
    def n():
        nonlocal a
        a=(a+0x6D2B79F5)&0xFFFFFFFF
        t=a; t=((t^(t>>15))*(t|1))&0xFFFFFFFF
        return ((t^(t>>14))&0xFFFFFFFF)/4294967296
    return n
VOW=set("aeiou")
def pig(w):
    i=0
    while i<len(w) and w[i] not in VOW: i+=1
    return w[i:]+w[:i]+"ay"

